import {Text, Switch, Avatar, TabList, Dialog, Table} from '@astryxdesign/core';

export function Panel({data}: {data: unknown[]}) {
  return (
    <>
      <Text color='accent'>Hi</Text>
      <Switch labelSpacing='hug' label="On" />
      <Avatar size='md' name="A" />
      <TabList />
      <Dialog position={{start: 0, top: 8}} />
      <Table data={data} aria-label='Rows' role='grid' />
    </>
  );
}
